"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import type { ComponentPropsWithoutRef, ReactElement, ReactNode } from "react";

import { cn } from "@/lib/utils";

/** Where the job behind a status badge stands. */
export type BadgeStatus = "idle" | "pending" | "success" | "failure";

/** Props for a status badge. The children are the visible label, such as "Deploying". */
export type StatusBadgeProps = Omit<ComponentPropsWithoutRef<"span">, "children"> & {
  status: BadgeStatus;
  children: ReactNode;
  /**
   * Reads each change aloud through a polite live region. Turn it off when many
   * badges change together, and announce one summary instead.
   */
  announce?: boolean;
};

const SWAP: Transition = { type: "spring", duration: 0.3, bounce: 0 };
// A fade is not motion, so reduced motion keeps it and drops the roll and blur.
const FADE: Transition = { duration: 0.15 };
const SHOWN = { opacity: 1, y: "0%", filter: "blur(0rem)" };

function DotGlyph() {
  return (
    <svg viewBox="0 0 16 16" aria-hidden="true" className="size-3.5">
      <circle cx="8" cy="8" r="3" fill="currentColor" />
    </svg>
  );
}

// The arc spins at a constant speed: it stands for time passing, so easing would make it pulse.
function SpinnerGlyph() {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.75"
      aria-hidden="true"
      className="size-3.5 motion-safe:animate-spin"
    >
      <circle cx="8" cy="8" r="5.5" className="opacity-25" />
      <path d="M8 2.5a5.5 5.5 0 0 1 5.5 5.5" strokeLinecap="round" />
    </svg>
  );
}

function CheckGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true" className="size-3.5">
      <path d="m3 8.5 3.25 3.25L13 5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

function CrossGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true" className="size-3.5">
      <path d="m4.5 4.5 7 7M11.5 4.5l-7 7" strokeLinecap="round" />
    </svg>
  );
}

const GLYPHS = {
  idle: DotGlyph,
  pending: SpinnerGlyph,
  success: CheckGlyph,
  failure: CrossGlyph,
} satisfies Record<BadgeStatus, () => ReactElement>;

// Success stays in the theme's own ink: the check carries the meaning, so the
// badge never depends on a green the theme may not define.
const TONES = {
  idle: "border-border bg-muted text-muted-foreground",
  pending: "border-border bg-muted text-foreground",
  success: "border-primary/25 bg-primary/10 text-foreground",
  failure: "border-destructive/30 bg-destructive/10 text-destructive",
} satisfies Record<BadgeStatus, string>;

/**
 * Shows the state of a running job, such as a deploy or an import. When the
 * status changes, the icon and the label roll to the new state.
 */
export function StatusBadge({ status, children, announce = true, className, ...spanProps }: StatusBadgeProps) {
  const reduceMotion = useReducedMotion();
  const Glyph = GLYPHS[status];
  const swap = reduceMotion ? FADE : SWAP;
  const enter = reduceMotion ? { opacity: 0 } : { opacity: 0, y: "60%", filter: "blur(0.25rem)" };
  const leave = reduceMotion ? { opacity: 0 } : { opacity: 0, y: "-60%", filter: "blur(0.25rem)" };

  return (
    <span
      {...spanProps}
      role={announce ? "status" : spanProps.role}
      data-status={status}
      className={cn(
        "inline-flex h-7 items-center gap-1.5 overflow-hidden whitespace-nowrap rounded-full border px-2.5 text-xs font-medium motion-safe:transition-colors motion-safe:duration-200",
        TONES[status],
        className,
      )}
    >
      {/* The rolling layer is decoration. The live region reads the plain label beside it. */}
      <span aria-hidden="true" className="relative inline-flex">
        <AnimatePresence mode="popLayout" initial={false}>
          <motion.span key={status} initial={enter} animate={SHOWN} exit={leave} transition={swap} className="inline-flex items-center gap-1.5">
            <Glyph />
            {children}
          </motion.span>
        </AnimatePresence>
      </span>
      <span className="sr-only">{children}</span>
    </span>
  );
}
